import { Table, StringColumn, BooleanColumn, ReferenceColumn } from '../../db'

export const sys_user_role = Table({
    name: 'sys_user_role',
    extends: 'sys_metadata',
    schema: {
        name: StringColumn({ mandatory: true }),
        description: StringColumn({ maxLength: 1000 }),
        elevated_privilege: BooleanColumn({ label: 'Elevated Privilege', default: false }),
        assignable_by: ReferenceColumn({ referenceTable: 'sys_user' }),
        can_delegate: BooleanColumn({ default: true }),
        grantable: BooleanColumn({ default: true }),
        includes_roles: StringColumn({}),
        scoped_admin: BooleanColumn({ default: false }),
        suffix: StringColumn({}),
    },
})
